nextflow_process {

    name "Test Process AMRFINDERPLUS_RUN"
    script "../main.nf"
    process "AMRFINDERPLUS_RUN"

    tag "modules"
    tag "modules_nfcore"
    tag "amrfinderplus"
    tag "amrfinderplus/run"
    tag "amrfinderplus/update"

    setup {

        run("AMRFINDERPLUS_UPDATE") {
            script "modules/nf-core/amrfinderplus/update/main.nf"
            process {
                """
                """
            }
        }
    }

    test("amrfinderplus/run - haemophilus_influenzae - genome_fna_gz") {

        when {
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + 'genomics/prokaryotes/haemophilus_influenzae/genome/genome.fna.gz', checkIfExists: true),
                    '',
                    false
                ]
                input[1] = AMRFINDERPLUS_UPDATE.out.db
                """
            }
        }

        then {
            // The database is downloaded live by AMRFINDERPLUS_UPDATE, so its version changes with each NCBI release
            def db_version_keys = ['db_version', 'versions_amrfinderplus_database']
            assertAll(
                { assert process.success },
                { assert process.out.db_version[0] ==~ /\d{4}-\d{2}-\d{2}\.\d+/ },
                { assert process.out.versions_amrfinderplus_database[0][2] ==~ /\d{4}-\d{2}-\d{2}\.\d+/ },
                { assert snapshot(sanitizeOutput(process.out).findAll { key, val -> !(key in db_version_keys) }).match() }
            )
        }
    }

