                { assert process.success },
                { assert process.out.db_version[0] ==~ /\d{4}-\d{2}-\d{2}\.\d+/ },
                { assert process.out.versions_amrfinderplus_database[0][2] ==~ /\d{4}-\d{2}-\d{2}\.\d+/ },
                { assert snapshot(sanitizeOutput(process.out).findAll { key, val -> !(key in db_version_keys) }).match() }
            )
        }
    }

